#include "bside/presets/BSidePresets.h"

#include "BSideFactoryData.h" // generated by juce_add_binary_data (CMakeLists.txt): presets/bside/factory/*.json
#include "common/params/GlobalParams.h"

namespace bs
{
vs::presets::Instrument bsideInstrument()
{
    vs::presets::Instrument i;
    i.id = kPresetInstrumentId;
    i.groups = 8;
    i.slotsPerGroup = 8;
    i.programExtension = ".bsprog";
    i.toneExtension = ".bstone";
    i.bankExtension = ".bsbank";
    return i;
}

vs::presets::Schema makeBSideSchema (const juce::AudioProcessor& processor)
{
    return vs::presets::Schema::fromProcessor (
        processor, { "lower.", "upper." },
        { vs::ParamID::masterVolume, vs::ParamID::masterLimiter, vs::ParamID::masterLimiterCeiling }, bsideInstrument());
}

vs::presets::Bank makeBSideFactoryBank (const vs::presets::Schema& schema, juce::StringArray* errors)
{
    std::vector<vs::presets::FactoryFile> files;
    for (int i = 0; i < bs_factory::namedResourceListSize; ++i)
    {
        int size = 0;
        const char* name = bs_factory::namedResourceList[i];
        const char* data = bs_factory::getNamedResource (name, size);
        files.push_back ({ juce::String::fromUTF8 (bs_factory::getNamedResourceOriginalFilename (name)), data, static_cast<size_t> (size) });
    }
    return vs::presets::makeBankFromFiles (schema, "Factory", files, errors);
}
} // namespace bs
